 0 AND 1), ADD COLUMN pitching_k_min numeric CHECK (pitching_k_min BETWEEN 0 AND 1), ADD COLUMN pitching_bb_max numeric CHECK (pitching_bb_max BETWEEN 0 AND 1), ADD COLUMN pitching_hr_max numeric CHECK (pitching_hr_max BETWEEN 0 AND 1), ADD COLUMN standards_source text NOT NULL DEFAULT 'Camryn Williams · October 26, 2026'; COMMENT ON COLUMN public.mastery_identity_settings.elite_home_runs IS 'DEPRECATED: replaced by elite_hr_rate'; COMMENT ON COLUMN public.mastery_identity_settings.lacking_power_home_runs IS 'DEPRECATED: replaced by lacking_power_hr_rate'; COMMENT ON COLUMN public.mastery_identity_settings.elite_balls_in_play_rate IS 'DEPRECATED: replaced by level-specific contact K/PA, whiff/swings and zone contact thresholds'; ALTER TABLE public.gp_games ADD COLUMN batters_faced integer CHECK (batters_faced>=0), ADD COLUMN pitching_history_complete boolean NOT NULL DEFAULT false; ALTER TABLE public.gp_pitches ADD COLUMN batter_opportunity integer CHECK (batter_opportunity>0), ADD COLUMN batter_result text CHECK (batter_result IN ('K','BB','HBP','HR','out','hit','error','sacrifice','interference')); COMMENT ON COLUMN public.gp_games.batters_faced IS 'Explicit completed BF total; never pitch count. Complete linked pitcher opportunity results take precedence when pitching_history_complete is true.'; COMMENT ON COLUMN public.gp_pitches.batter_opportunity IS 'Explicit within-game pitcher batter opportunity number, not opponent name or pitch count'; COMMENT ON COLUMN public.gp_pitches.batter_result IS 'Explicit final outcome of this pitcher batter opportunity; only a final pitch carries an outcome.';